import { LitElement, css, html } from "lit";
import { customElement, property } from "lit/decorators.js";

/**
 * Tab item from the jz-tab-item capture. Figma `State` (default | Selected)
 * maps to the `selected` boolean — not an `interactive` axis.
 * Text is `label`. Optional `href` renders a link instead of a button.
 */
@customElement("jz-tab-item")
export class JzTabItemElement extends LitElement {
  static override styles = css`
    :host {
      display: inline-block;
    }

    .tab {
      box-sizing: border-box;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      margin: 0;
      border: none;
      background: transparent;
      box-shadow: none;
      border-radius: var(--jz-primitive-radius-md);
      padding: var(--jz-semantic-space-padding-xs)
        var(--jz-semantic-space-padding-sm);
      font: var(--jz-semantic-type-body-regular-font);
      color: var(--jz-semantic-color-text-default);
      cursor: pointer;
      text-decoration: none;
    }

    .tab:focus-visible {
      outline: var(--jz-primitive-stroke-width-md) solid
        var(--jz-semantic-color-border-strong);
      outline-offset: var(--jz-primitive-stroke-width-md);
    }

    :host([selected]) .tab {
      background: var(--jz-semantic-color-background-control-default);
      box-shadow: var(--jz-primitive-effect-elevation-low);
    }
  `;

  @property({ type: String })
  label = "label";

  /**
   * When set, the tab is an `<a>` for navigation. When empty, it is a
   * `<button>` (in-page selection only).
   */
  @property({ type: String, reflect: true })
  href = "";

  /** Selection key for `jz-tab-group` `selected-tab`. Falls back to index. */
  @property({ type: String, reflect: true })
  value = "";

  /** Figma State=Selected. */
  @property({ type: Boolean, reflect: true })
  selected = false;

  override render() {
    if (this.href) {
      return html`<a
        class="tab"
        href=${this.href}
        role="tab"
        aria-selected=${this.selected ? "true" : "false"}
      >
        ${this.label}
      </a>`;
    }

    return html`<button
      class="tab"
      type="button"
      role="tab"
      aria-selected=${this.selected ? "true" : "false"}
    >
      ${this.label}
    </button>`;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    "jz-tab-item": JzTabItemElement;
  }
}
